class Solution {
    public int findTheLongestSubstring(String text){
        int[] earliest=new int[32];
        Arrays.fill(earliest,-2);
        earliest[0]=-1;
        int mask=0,answer=0;
        for(int i=0;i<text.length();i++){
            int vowel="aeiou".indexOf(text.charAt(i));
            if(vowel>=0)mask^=1<<vowel;
            if(earliest[mask]!=-2)answer=Math.max(answer,i-earliest[mask]);
            else earliest[mask]=i;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun findTheLongestSubstring(text:String):Int{
        val earliest=IntArray(32){
            -2
        };
        earliest[0]=-1;
        var mask=0;
        var answer=0;
        for(i in text.indices){
            val vowel="aeiou".indexOf(text[i]);
            if(vowel>=0)mask=mask xor (1 shl vowel);
            if(earliest[mask]!=-2)answer=maxOf(answer,i-earliest[mask])else earliest[mask]=i
        };
        return answer
    }
}

